const crypto = require('crypto');

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set');

const PATH = '/webhook/lendloop-loan-events';
const TOLERANCE_SECONDS = 300;

const item = $input.first();
// The HMAC covers the exact bytes Convex sent, so verify the raw body rather than parsed JSON.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const header = item.json.headers['x-lendloop-signature'] || '';
const match = header.match(/^t=(\d{1,12}),v1=([0-9a-f]{64})$/i);

let valid = false;
if (match) {
  const t = Number(match[1]);
  const fresh = Math.abs(Date.now() / 1000 - t) <= TOLERANCE_SECONDS;
  const expected = crypto.createHmac('sha256', secret).update(`${t}.POST.${PATH}.${raw}`).digest();
  const given = Buffer.from(match[2], 'hex');
  valid = fresh && crypto.timingSafeEqual(expected, given);
}
if (!valid) return [{ json: { valid: false } }];

// Allowlist: nothing else from the request travels further through this workflow.
const { eventId, event, toolName, startDate, endDate, recipient } = JSON.parse(raw);
return [{ json: { valid: true, eventId, event, toolName, startDate, endDate, recipient } }];

// MOCK SENDER. In production, replace this node with an Email/Slack node using an n8n credential.
// The address is masked in logs: the mock proves routing without writing personal data to stdout.
const { eventId, event, toolName, startDate, endDate, recipient } = $input.first().json;

if ($env.LENDLOOP_SIMULATE_SEND_FAILURE === 'true') {
  throw new Error('Simulated notification provider outage');
}

const dates = `${startDate} to ${endDate}`;
const MESSAGES = {
  'loan.requested': `A neighbor would like to borrow your ${toolName} (${dates}).`,
  'loan.approved': `Good news: your request for the ${toolName} (${dates}) was approved.`,
  'loan.declined': `Your request for the ${toolName} (${dates}) was declined.`,
  'loan.cancelled': `The loan of the ${toolName} (${dates}) was cancelled.`,
  'loan.returned': `The ${toolName} was marked as returned. Thanks for borrowing responsibly!`,
};
const text = MESSAGES[event];
if (!text) throw new Error(`Unknown event type: ${event}`);

const [local, domain] = recipient.email.split('@');
console.log(JSON.stringify({
  type: 'lendloop.notification.sent',
  eventId,
  event,
  to: `${local.slice(0, 1)}***@${domain}`,
  message: `Hi ${recipient.firstName}! ${text}`,
}));

return [{ json: { eventId } }];

const crypto = require('crypto');

// Same scheme as convex/lib/signature.ts: t=<unix>,v1=hmac_sha256("<t>.<METHOD>.<path>.<body>")
function sign(method, path, body) {
  const secret = $env.LENDLOOP_INBOUND_SECRET;
  if (!secret) throw new Error('LENDLOOP_INBOUND_SECRET is not set');
  const t = Math.floor(Date.now() / 1000);
  const mac = crypto.createHmac('sha256', secret).update(`${t}.${method}.${path}.${body}`).digest('hex');
  return `t=${t},v1=${mac}`;
}

const body = JSON.stringify({ eventId: $input.first().json.eventId });
return [{ json: { body, signature: sign('POST', '/n8n/notification-status', body) } }];
